<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProvider;

/**
 * @template-extends ArrayIterator<int, TenantLoginProvider>
 */
class TenantLoginProviderSlide extends \ArrayIterator
{
    private readonly ?TenantLoginProvider $last;
    private readonly TenantLoginProviderCursor $nextCursor;
    public function __construct(
        private readonly ?\Closure $next,
        private readonly ?TenantLoginProviderCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
        $this->last = $values ? end($values) : null;
        $cursor = $this->cursor;
        $last = $this->last;
        $this->nextCursor = new TenantLoginProviderCursor(
            limit: null === $cursor ? 1000 : $cursor->limit(),
            sinceUid: null == $last ? null : $last->uid(),
            sinceName: null === $last ? null : $last->getName(),
        );
    }
    public function cursor(): ?TenantLoginProviderCursor
    {
        return $this->cursor;
    }
    public function nextCursor(): TenantLoginProviderCursor
    {
        return $this->nextCursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?TenantLoginProvider
    {
        return parent::current();
    }
    public function map(\Closure $fn): TenantLoginProviderSlide
    {
        return new TenantLoginProviderSlide($this->next, $this->cursor, array_map($fn, $this->values));
    }
    public function slide(\Closure $fn): TenantLoginProviderSlide
    {
        $filtered = array_filter($this->values, $fn);
        $collected = $filtered;
        $last = $this->last;
        $next = $this->next;
        $cursor = $this->cursor;
        if (null !== $cursor && count($collected) == $cursor->limit()) {
            while (count($collected) < count($this->values) && $next !== null) {
                if ($last === null) {
                    break;
                }
                $nextSlide = $next($this, $cursor->next($last, $cursor->limit()));
                if (count($nextSlide)) {
                    $nextFiltered = array_filter($nextSlide->values, $fn);
                    $collected = array_merge($collected, $nextFiltered);
                    $cursor = $nextSlide->cursor;
                    $next = $nextSlide->next;
                    $last = $nextSlide->last;
                } else {
                    break;
                }
            }
            return new TenantLoginProviderSlide($next, $cursor, $collected);
        } else {
            return $this;
        }
    }
}
